/**
 * brain_manager HTTP 客户端：面板只通过它读写管理器。
 * 地址默认本机 19998，可由宿主插件用 BRAIN_MANAGER_URL 覆盖并经
 * /brain-console/api/config 下发给浏览器（启动时 setApiBase）。
 *
 * 这里同时放几个模块级常量加载函数（备份/缓存/失败边/历史）——引用稳定，
 * 对话框只在挂载时拉一次列表，不会因为父组件重渲染而反复请求。
 */
import type {
  BackupListing, BatchRestartResult, BatchStartResult, BatchStopResult, CacheListing, CachePruneResult,
  AutoRecoverStatus, CheckupResult, EmbedJobStatus, StorageSummary, StorageThresholds, TableInfo, TableUsage, FailedEdgesListing, HistoryListing, IndexHealth, PruneResult, RestoreResult, TrendThresholds, Unit, UnitAction,
} from './ui/types.ts'

/** brain_manager 的 HTTP 地址。 */
/** 管理器默认地址；宿主未下发配置时使用。 */
let apiBase = 'http://127.0.0.1:19998'

/**
 * 覆盖管理器地址（去掉结尾斜杠）。
 * @param url - 完整 http(s) 地址
 */
export function setApiBase(url: string): void {
  if (url !== '') apiBase = url.replace(/\/+$/, '')
}

/**
 * 当前管理器地址（用于提示文案）。
 * @returns 管理器地址
 */
export const apiBaseUrl = (): string => apiBase

/** 宿主下发的路径/地址配置。 */
export interface PanelConfigView {
  brainRoot: string
  managerUrl: string
  namedLauncher: string
  launcherPath: string
  scriptPath: string
  logPath: string
  namedLauncherExists: boolean
  launcherExists: boolean
  scriptExists: boolean
  pythonw: string
  configFile: string
  sources: { brainRoot: 'file' | 'env' | 'none'; managerUrl: 'file' | 'env' | 'default' }
}

/**
 * 读取宿主配置（同源路由，不走管理器地址）。
 * @returns 宿主生效配置
 */
export const loadPanelConfig = async (): Promise<PanelConfigView> => {
  const response = await fetch('/brain-console/api/config', { cache: 'no-store' })
  if (!response.ok) throw new Error(`宿主配置接口不可用（${response.status}）`)
  const data = await response.json() as Partial<PanelConfigView>
  // 旧版宿主只返回 {managerUrl}：提示需要重启 DSH 才能配置路径
  if (typeof data.managerUrl !== 'string' || typeof data.brainRoot !== 'string') {
    throw new Error('宿主为旧版（仅下发 managerUrl）')
  }
  return data as PanelConfigView
}

/**
 * 保存宿主配置（Brain 根目录 / 管理器地址）。
 * @param patch - 待更新字段；空字符串表示清除并回退环境变量
 * @returns 保存结果与新的生效配置
 */
export const savePanelConfig = async (
  patch: { brainRoot?: string; managerUrl?: string },
): Promise<{ ok: boolean; error?: string; config?: PanelConfigView }> => {
  const response = await fetch('/brain-console/api/config', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(patch),
  })
  try {
    return await response.json() as { ok: boolean; error?: string; config?: PanelConfigView }
  } catch {
    return { ok: false, error: `保存失败（${response.status}）` }
  }
}

/** 单元动作的中文名。 */
export const ACTION_LABEL: Record<UnitAction, string> = { start: '启动', stop: '停止', restart: '重启' }

/** 从 `<name>:<action>` 里取出正在执行的动作；不属于该单元则为 null。 */
export function busyActionOf(busy: string | null, name: string): UnitAction | null {
  if (busy === null) return null
  const [unit, action] = busy.split(':')
  if (unit !== name) return null
  return action === 'start' || action === 'stop' || action === 'restart' ? action : null
}

/** GET 并解析 JSON（失败抛 HTTP 状态）。 */
export async function jget<T>(path: string): Promise<T> {
  const res = await fetch(`${apiBase}${path}`, { cache: 'no-store' })
  if (!res.ok) throw new Error(`HTTP ${res.status}`)
  return (await res.json()) as T
}

/** POST 并解析 JSON 应答（清理备份要读回删了哪些、释放多少）。 */
export async function postJson<T>(path: string, body?: unknown): Promise<T> {
  const res = await fetch(`${apiBase}${path}`, {
    method: 'POST',
    headers: body === undefined ? undefined : { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  })
  if (!res.ok) throw new Error(`HTTP ${res.status}`)
  return (await res.json()) as T
}

/** POST 且不关心响应体（启停/设置类动作）。 */
export async function postManager(path: string, body?: unknown): Promise<void> {
  await postJson<unknown>(path, body)
}

